---@type ECSComponent
local ECSComponent = import("Frame.ECS.ECSComponent")
---@class TriggerGiftComponent
local TriggerGiftComponent = Class("TriggerGiftComponent", ECSComponent)
---@type PlayerComponent
local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
---@type PlayerDojo
local playerDojo =  PlayerComponent:GetPlayerDojo()
---@class TriggerGiftData
---触发礼包配表数据对象
local TriggerGiftData = {}
function TriggerGiftData.New(data)
    ---@type TriggerGiftData
    local this = {}
    this.id = checkNumber(data.id)
    this.productId = checkInt(data.productId) --礼包id
    this.type = data.type --类型
    this.expirationTime = playerDojo:GetServerTime() + data.expirationTime    --礼包剩余时间
    this.channelProductId = data.channelProductId
    this.rewards = data.rewards --奖励道具(List)
    this.consume = data.consume --消耗道具(List)
    this.price = data.price 
    this.portrait = data.portrait 
    this.windowsPriceId = data.windowsPriceId 
    this.prices = data.prices 
    return this
end

---@class TriggerGift
---触发礼包对象
local TriggerGift = {}
function TriggerGift.New(data, timer)
    ---@type TriggerGift
    local this = {}
    this.id = checkNumber(data.id)
    this.rewards = checkTable(data.rewards)
    this.productId = checkInt(data.productId)
    this.expirationTime = playerDojo:GetServerTime() + data.expirationTime
    this.channelProductId = data.channelProductId
    this.portrait = data.portrait 
    this.dataConfig = data
    this.windowsPriceId = data.windowsPriceId
    this.price = checkNumber(data.price)
    return this
end

function TriggerGiftComponent:__init()
    ECSComponent.__init(self)
    self:InitField()
    self.eventCacheTrigger = Events.AddListener(Constants.EventNames.TriggerGiftCachePop,Bind(self, self.TriggerGiftCachePopEventHandler))
end

function TriggerGiftComponent:__delete()
    self:CleanField()
    if self.eventCacheTrigger then
        Events.RemoveListener(Constants.EventNames.TriggerGiftCachePop ,self.eventCacheTrigger)
        self.eventCacheTrigger = nil 
    end
end

function TriggerGiftComponent:CleanField()
    self.triggerChest = nil -- 当前可购买的触发礼包
    self.cacheTriggerChest = nil
    self.isPopUpTriggerGift = nil
end

function TriggerGiftComponent:InitField()
    self.cacheTriggerChest = {}
    self.triggerChest = {}
    self.isPopUpTriggerGift = false
end
function TriggerGiftComponent:IsNeedOpenTriggerGift()
    local isOpen = false
    local triggerGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TriggerGiftComponent)
    local isPopUpTriggerGift = triggerGiftComponent:GetIsPopUpTriggerGift()
    if not isPopUpTriggerGift then
        local listGift = triggerGiftComponent:GetEffectTriggerGift()
        if table.count(listGift) > 0 then
            isOpen = true
        end
    else
        local cacheGift = triggerGiftComponent:GetCacheTriggerGift()
        if table.count(cacheGift) > 0 then
            isOpen = true
        end
    end
    return isOpen
end

function TriggerGiftComponent:TriggerGiftCachePopEventHandler()
    local GuideUtils = import('Game.UI.Guide.GuideUtils')
    if GuideUtils.IsInGuiding() then
        return
    end     
    -- local cacheGift = self:GetCacheTriggerGift()
    local isOpen = self:IsNeedOpenTriggerGift()
    if isOpen then
        xRecord.record('3-023')
        local UIModule = CS.Engine.UI.UIModule
        local isPopUpTriggerGift = self:GetIsPopUpTriggerGift()
        if not  isPopUpTriggerGift then
            self:SetIsPopUpTriggerGift(true)
            local listGift = self:GetEffectTriggerGift()
            if table.count(listGift) > 0  then
                xRecord.record('3-023')
                UIModule.OpenDialog({ id = Constants.UITypeIds.TriggerGiftBag, parameters = {isPopUp = true } })    
            end 
        else
            local cached = self:GetCacheTriggerGift()
            if table.count(cached) > 0  then   
                xRecord.record('3-023')             
                UIModule.OpenDialog({ id = Constants.UITypeIds.TriggerGiftBag, parameters = {isPopUp = true, isCache = true} })
            end
        end
    end
end

---FillGiftData
---填充礼包数据, giftReq 和 CheckIn
---@param data table
--data.id --礼包id
--data.type --类型
--data.activatedNum --解锁条件(List)
--data.expirationTime --礼包剩余时间
--data.rewards --奖励道具(List)
--data.consume --消耗道具(List)
function TriggerGiftComponent:FillGiftData(data,isCache)
    xTry(function()
        if isNull(self.triggerChest) then self.triggerChest = {} end
        if isNull(self.cacheTriggerChest) then self.cacheTriggerChest = {} end
        data = checkTable(data)
        -- print("->TriggerGiftComponent:FillGiftData", table.dump(data))
        for i, gift in pairs(data) do
            self:InsertGift2List(gift,isCache)
        end
    end)
end

function TriggerGiftComponent:GetEffectTriggerGift()
    local count = #self.triggerChest
    local currentTime = playerDojo:GetServerTime()
    for i = count , 1 , -1 do
        if currentTime >= self.triggerChest[i].giftData.expirationTime then
            table.remove(self.triggerChest,i)
        end
    end
    return self.triggerChest
end

function TriggerGiftComponent:GetLastCacheTriggerGift()
    local data = {}
    if table.count(self.cacheTriggerChest) > 0 then
        table.insert(data,self.cacheTriggerChest[#self.cacheTriggerChest])
        return data
    else
        printError("cacheTriggerChest 长度为0 不应该调用到 isCache 为true")
    end
    return data
end

function TriggerGiftComponent:GetCacheTriggerGift()
    local count = #self.cacheTriggerChest
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local currentTime = playerComponent:GetPlayerDojo():GetServerTime()
    for i = count , 1 , -1 do
        if currentTime >= self.cacheTriggerChest[i].giftData.expirationTime then
            table.remove(self.cacheTriggerChest,i)
        end
    end
    return self.cacheTriggerChest
end

function TriggerGiftComponent:InsetDataToTriggerChest(data)
    local currentTime = playerDojo:GetServerTime()
    ---如果时间结束的  不要
    if currentTime >= data.giftData.expirationTime then
        return
    end
    --- 查看礼包是否在列表中
    local _GetGift = function(id)
        for i, giftChest in pairs(self.triggerChest) do
            local giftId = giftChest.giftData.id
            if checkInt(id) == checkInt(giftId) then
                return true
            end
        end
        return false
    end

    if not _GetGift(data.giftData.id) then
        table.insert(self.triggerChest,data)
    end
end
---移除掉最后一位 然后放放到TriggerChest中
function TriggerGiftComponent:RemoveLastCacheTriggerChest()
    local lastData
    if table.count(self.cacheTriggerChest) > 0 then
        lastData = clone(self.cacheTriggerChest[#self.cacheTriggerChest])
       table.remove(self.cacheTriggerChest,#self.cacheTriggerChest)
    end
    if not isNull(lastData) then
        self:InsetDataToTriggerChest(lastData)
    end
end

function TriggerGiftComponent:InsertGift2List(data,isCache)
    local giftConfigData = TriggerGiftData.New(data)
    --- 查看礼包是否在列表中
    local _GetGift = function(id)
        for i, giftChest in pairs(self.triggerChest) do
            local giftId = giftChest.giftData.id 
            if checkInt(id) == checkInt(giftId) then
                return true
            end
        end
        return false
    end

    if not _GetGift(data.id) then
        ---如果没有弹出过界面  这个时候直接放到列表中
        local triggerGiftData = TriggerGift.New(data)
        if isCache and self.isPopUpTriggerGift then
            if table.count(self.cacheTriggerChest) >= 3 then
                local data = self.cacheTriggerChest[1]
                self:InsetDataToTriggerChest(data)
                table.remove(self.cacheTriggerChest,1)
            end
            table.insert(self.cacheTriggerChest, { giftData = triggerGiftData, configData = giftConfigData })
        else
            table.insert(self.triggerChest, { giftData = triggerGiftData, configData = giftConfigData })
        end
    end
end

------------ Timers ------------

function TriggerGiftComponent:GetLongestTimes()
    local count = 0
    for i, vGift in pairs(self.triggerChest) do
        local giftData = vGift.giftData
        local giftCount = giftData.expirationTime
        if giftCount >= count then
            count = giftCount
        end
    end

    for i, vGift in pairs(self.cacheTriggerChest) do
        local giftData = vGift.giftData
        local giftCount = giftData.expirationTime
        if giftCount >= count then
            count = giftCount
        end
    end

    return count - playerDojo:GetServerTime()
end

