------------ HttpReq ------------
function TriggerGiftComponent:TriggerGiftReq(cb)
    GameUtils.Request(Interfaces.TriggerChest, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        self.triggerChest = {}
        local data = checkTable(jsonData.triggerChest)
    
        self:FillGiftData(data)
        if cb then cb(data) end
        Events.Broadcast(Constants.EventNames.TriggerGiftRefresh,{})
    end)
end

function TriggerGiftComponent:TriggerCacheGiftReq(isClean,cb)
    GameUtils.Request(Interfaces.TriggerChest, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        ---如果购买成功了 这时候要把cache清了
        if isClean then
            self.cacheTriggerChest = {}
        end
        local jsonData = response.data
    
        local data = checkTable(jsonData.triggerChest)
        self:FillGiftData(data,true)
        if cb then cb(data) end
        Events.Broadcast(Constants.EventNames.TriggerGiftRefresh,{})
    end)
end

function TriggerGiftComponent:GetIsPopUpTriggerGift()
    return self.isPopUpTriggerGift
end

function TriggerGiftComponent:SetIsPopUpTriggerGift(isPopUp)
    self.isPopUpTriggerGift = isPopUp
end

